import{_ as s,o as a,c as t,a6 as n}from"./chunks/framework.BrkgobfX.js";const h=JSON.parse('{"title":"Plugins","description":"Claude Code 中文手册 · 插件的组成、目录结构、Marketplace 安装分发、作者侧打包与团队 settings","frontmatter":{"title":"Plugins","description":"Claude Code 中文手册 · 插件的组成、目录结构、Marketplace 安装分发、作者侧打包与团队 settings","source":"https://daiw.org/manual/claude-code/plugins"},"headers":[],"relativePath":"manual/agent/claude-code/plugins.md","filePath":"manual/agent/claude-code/plugins.md"}'),d={name:"manual/agent/claude-code/plugins.md"};function i(o,e,l,c,p,r){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><blockquote><p>Claude Code 中文手册 · 插件的组成、目录结构、Marketplace 安装分发、作者侧打包与团队 settings</p></blockquote><p><strong>Plugins（插件）</strong> 是 Claude Code 的<strong>打包与分发层</strong>：把 <a href="/Front2Full/manual/agent/claude-code/custom-commands">Commands</a>、<a href="/Front2Full/manual/agent/claude-code/skills">Skills</a>、<a href="/Front2Full/manual/agent/claude-code/agents">Agents</a>，连同 hooks、MCP 服务器、LSP 服务器等，装进一个<strong>自包含目录</strong>，做成可版本化、可一键安装、可跨项目与团队共享的单元。前三篇讲「怎么写单个能力」，这一篇讲「怎么把它们打成一个包发出去、别人怎么装」。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>单独放在 <code>.claude/</code> 下的技能/命令/agent 只在<strong>当前项目</strong>可用、名字是 <code>/hello</code>；打成插件后可通过 <strong>Marketplace</strong> 分发、带版本、跨项目复用，代价是技能名带命名空间前缀 <code>/插件名:hello</code>。先用 <code>.claude/</code> 快速试，成型了再打包成插件。</p></div><h2 id="独立配置-vs-插件" tabindex="-1">独立配置 vs 插件 <a class="header-anchor" href="#独立配置-vs-插件" aria-label="Permalink to &quot;独立配置 vs 插件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>独立配置（<code>.claude/</code>）</th><th>插件（Plugin）</th></tr></thead><tbody><tr><td>技能名</td><td><code>/hello</code></td><td><code>/插件名:hello</code>（带命名空间，避免多插件重名冲突）</td></tr><tr><td>作用域</td><td>单个项目或个人</td><td>可跨项目、跨团队分发</td></tr><tr><td>分发</td><td>手动复制</td><td><code>/plugin install</code>，走 Marketplace</td></tr><tr><td>版本</td><td>无</td><td>有版本号或 git commit SHA</td></tr><tr><td>适合</td><td>个人工作流、项目定制、快速试验</td><td>团队统一、社区发布、versioned 发布</td></tr></tbody></table><h2 id="插件能打包什么" tabindex="-1">插件能打包什么 <a class="header-anchor" href="#插件能打包什么" aria-label="Permalink to &quot;插件能打包什么&quot;">​</a></h2><p>一个插件目录里，除清单外的组件都放在<strong>插件根目录</strong>（不是 <code>.claude-plugin/</code> 里）：</p><table tabindex="0"><thead><tr><th>目录 / 文件</th><th>组件</th></tr></thead><tbody><tr><td><code>.claude-plugin/plugin.json</code></td><td>插件清单（名字、描述、版本）</td></tr><tr><td><code>skills/&lt;name&gt;/SKILL.md</code></td><td>技能（推荐新写法）</td></tr><tr><td><code>commands/*.md</code></td><td>旧版扁平命令文件（兼容，新插件用 <code>skills/</code>）</td></tr><tr><td><code>agents/</code></td><td>自定义 subagent 定义</td></tr><tr><td><code>hooks/hooks.json</code></td><td>生命周期 hooks</td></tr><tr><td><code>.mcp.json</code></td><td>MCP 服务器配置</td></tr><tr><td><code>.lsp.json</code></td><td>LSP 语言服务器（代码智能）</td></tr><tr><td><code>monitors/monitors.json</code></td><td>后台监视器（watch 日志/文件，有事件就通知 Claude）</td></tr><tr><td><code>bin/</code></td><td>可执行文件，启用插件期间加入 Bash 工具的 <code>PATH</code></td></tr><tr><td><code>settings.json</code></td><td>启用插件时应用的默认设置（目前仅 <code>agent</code>、<code>subagentStatusLine</code> 两个键生效；v2.1.293 起 <code>subagentStatusLine</code> 负载新增 <code>agentType</code>）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>最常见的错误</strong>：把 <code>commands/</code>、<code>agents/</code>、<code>skills/</code>、<code>hooks/</code> 放进了 <code>.claude-plugin/</code> 目录里。<code>.claude-plugin/</code> 里<strong>只放 <code>plugin.json</code></strong>，其余全部放在插件根目录。插件根是插件自己的目录（你 <code>--plugin-dir</code> 指向的那个），<strong>永远不是 <code>~/.claude/</code></strong>。</p></div><h2 id="安装与使用-用户侧" tabindex="-1">安装与使用（用户侧） <a class="header-anchor" href="#安装与使用-用户侧" aria-label="Permalink to &quot;安装与使用（用户侧）&quot;">​</a></h2><p><code>/plugin</code> 打开插件管理面板，四个 tab 用 <code>Tab</code> 循环切换：</p><ul><li><strong>Discover</strong> —— 浏览已添加 Marketplace 里的插件</li><li><strong>Installed</strong> —— 查看/启用/禁用/卸载已装插件</li><li><strong>Marketplaces</strong> —— 增删、刷新 Marketplace</li><li><strong>Errors</strong> —— 插件加载错误</li></ul><p>官方 Marketplace <code>claude-plugins-official</code> 开箱即用，直接装：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/plugin install github@claude-plugins-official</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>常用命令（交互式 <code>/plugin ...</code> 与非交互式 <code>claude plugin ...</code> 一一对应，后者别名 <code>claude plugins</code>，适合脚本/CI）：</p><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/plugin install &lt;名&gt;@&lt;市场&gt;</code></td><td>安装某插件</td></tr><tr><td><code>/plugin install &lt;名&gt; --marketplace &lt;来源&gt;</code></td><td>🆕 <strong>v2.1.275+</strong>：先提议添加该 marketplace，再安装插件（🆕 v2.1.292 起命令行 <code>claude plugin install &lt;名&gt; --marketplace &lt;来源&gt;</code> 也支持，按与 <code>marketplace add</code> 相同的策略校验自动添加市场再安装）</td></tr><tr><td><code>claude plugin install</code> / <code>update</code> 加 <code>--accept-command &lt;sha256&gt;</code></td><td>🆕 <strong>v2.1.271+</strong>：精确接受上一次 <code>--json</code> 运行所显示的那条命令，代替 <code>-y</code></td></tr><tr><td><code>/plugin list [--enabled|--disabled]</code></td><td>列出已装插件</td></tr><tr><td><code>/plugin enable</code> / <code>disable &lt;名&gt;@&lt;市场&gt;</code></td><td>启用/禁用（不卸载）</td></tr><tr><td><code>/plugin uninstall &lt;名&gt;@&lt;市场&gt;</code></td><td>彻底卸载</td></tr><tr><td><code>/reload-plugins [--force]</code></td><td>不重启会话即应用插件变更；若会改动已加载的 MCP 工具集（使 prompt 缓存失效），需 <code>--force</code>。⚠️ v2.1.268 起用 <code>/plugin</code> 安装、启用、禁用的改动在关闭菜单时即生效，不再需要这一步</td></tr></tbody></table><p>🆕 v2.1.275 起，claude.ai 账号上启用的插件会同步到用该账号登录的终端会话，设置 <code>syncClaudeAiPlugins: false</code> 可以关闭；v2.1.273 起用 Claude 账号登录时也会请求访问你 claude.ai 上的插件。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>⚠️ 插件会以<strong>你的用户权限执行任意代码</strong>（hooks、MCP 服务器、<code>bin/</code> 脚本都是）。<strong>只安装你信任来源的插件、只添加你信任的 Marketplace</strong>。Anthropic 不审核第三方插件里打包了什么。企业可用托管设置的 <code>strictKnownMarketplaces</code> 限制可添加的来源。</p></div><h2 id="marketplace-插件市场" tabindex="-1">Marketplace（插件市场） <a class="header-anchor" href="#marketplace-插件市场" aria-label="Permalink to &quot;Marketplace（插件市场）&quot;">​</a></h2><p>Marketplace 是一份<strong>插件目录</strong>，本质是一个含 <code>.claude-plugin/marketplace.json</code> 的 git 仓库（或本地路径、远程 URL）。用它分两步：先 <code>add</code> 注册目录，再 <code>install</code> 挑装。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 从 GitHub owner/repo 添加(可 @ref 固定分支/tag);别名 /plugin market</span></span>
<span class="line"><span>/plugin marketplace add anthropics/claude-code</span></span>
<span class="line"><span># 从任意 git host(带 https:// 与 .git),或本地路径</span></span>
<span class="line"><span>/plugin marketplace add https://gitlab.com/company/plugins.git</span></span>
<span class="line"><span>/plugin marketplace add ./my-marketplace</span></span>
<span class="line"><span># 刷新 / 移除(别名 rm)</span></span>
<span class="line"><span>/plugin marketplace update [名字]</span></span>
<span class="line"><span>/plugin marketplace remove &lt;名字&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>Anthropic 维护三个公共 Marketplace：</p><table tabindex="0"><thead><tr><th>Marketplace</th><th>添加方式</th><th>内容</th></tr></thead><tbody><tr><td><code>claude-plugins-official</code></td><td>自动可用</td><td>官方精选：代码智能 LSP（<code>typescript-lsp</code>、<code>pyright-lsp</code>、<code>gopls-lsp</code>、<code>rust-analyzer-lsp</code> 等）、外部集成 MCP（<code>github</code>、<code>gitlab</code>、<code>linear</code>、<code>notion</code>、<code>figma</code>、<code>slack</code>、<code>sentry</code> 等）、<code>security-guidance</code>、<code>commit-commands</code>、<code>pr-review-toolkit</code>、<code>plugin-dev</code></td></tr><tr><td><code>claude-community</code></td><td><code>/plugin marketplace add anthropics/claude-plugins-community</code></td><td>通过审核的第三方插件，装为 <code>&lt;名&gt;@claude-community</code></td></tr><tr><td><code>claude-code-plugins</code>（示例）</td><td><code>/plugin marketplace add anthropics/claude-code</code></td><td>官方演示插件，展示能做什么</td></tr></tbody></table><blockquote><p><code>claude-plugins-official</code>、<code>claude-community</code> 等名字为官方保留，第三方 Marketplace 不能占用。⚠️ v2.1.280 起名字模仿保留名的 Marketplace 在添加时就被拒绝，已经添加的也会停止加载。</p></blockquote><h2 id="写一个插件-作者侧" tabindex="-1">写一个插件（作者侧） <a class="header-anchor" href="#写一个插件-作者侧" aria-label="Permalink to &quot;写一个插件（作者侧）&quot;">​</a></h2><p>最小插件 = 一个清单 + 一个技能。以下从零建一个 <code>my-first-plugin</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-first-plugin/.claude-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-first-plugin/skills/hello</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>清单 <code>my-first-plugin/.claude-plugin/plugin.json</code>：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-first-plugin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;A greeting plugin to learn the basics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Your Name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>技能 <code>my-first-plugin/skills/hello/SKILL.md</code>：</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Greet the user with a friendly message</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">disable-model-invocation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Greet the user warmly and ask how you can help them today.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>本地加载测试（不必先发布），然后调用带命名空间的技能：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --plugin-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-first-plugin</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 可重复传多次;也接受 .zip(v2.1.128+)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 会话内:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/my-first-plugin:hello</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>v2.1.265 起 <code>--plugin-dir</code> 还能指向<strong>装着多个插件的父目录</strong>：每个带清单的子目录各算一个插件，运行中增删子目录也会被发现，适合同时开发一组插件（v2.1.281 修复了这样的父目录里同时带 <code>.claude-plugin/marketplace.json</code> 时只加载出一个空插件）。v2.1.280 起也可以用环境变量 <code>CLAUDE_CODE_PLUGIN_DIRS</code> 列出要加载的目录：Unix 用 <code>:</code>、Windows 用 <code>;</code> 分隔，须为绝对路径或以 <code>~</code> 开头。</p><p>清单 <code>plugin.json</code> 字段：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><code>name</code></td><td>唯一标识，也是技能命名空间前缀（<code>/name:skill</code>）</td></tr><tr><td><code>description</code></td><td>插件管理器里展示的描述</td></tr><tr><td><code>version</code></td><td>可选。设了它，用户仅在你 bump 版本号时才收到更新；<strong>省略且用 git 分发时，每个 commit 的 SHA 都算新版本</strong></td></tr><tr><td><code>author</code> / <code>homepage</code> / <code>repository</code> / <code>license</code></td><td>可选，元数据</td></tr></tbody></table><p>改动后 <code>/reload-plugins</code> 热重载，无需重启。想验证清单/YAML 是否合法，跑 <code>claude plugin validate .</code>（或会话内 <code>/plugin validate .</code>）——v2.1.221 起它还会在 marketplace 名或插件名可能被 Claude Desktop 的托管同步拒绝时给出告警。技能路径也从该版本起接受 <code>&quot;.&quot;</code>（表示插件根目录）。v2.1.259 起 <code>validate</code> 支持 <code>--json</code>，输出机器可读的校验报告。🆕 v2.1.281 起它还检查插件声明的 MCP 服务器（加载时会被静默丢弃的条目、未声明的 <code>\${user_config.*}</code> 引用、不安全的 URL），并在 shell 形式的 hook 没给 <code>\${CLAUDE_PLUGIN_ROOT}</code> 加引号时告警（插件路径含空格就会出错）；v2.1.283 起 Claude Code 实际装不上的插件或 marketplace 名字，以及缺失或越出插件目录的 <code>outputStyles</code> / <code>themes</code> / <code>monitors</code> / <code>lspServers</code> 路径都会校验失败。</p><p>🆕 <strong>v2.1.269 起还有 <code>claude plugin eval</code></strong>：对插件跑它自带的评测套件，给出可复现的打分结果（JSON + HTML 报告），适合发布前做回归，具体参数见 <code>claude plugin eval --help</code>（🆕 v2.1.299 起新增 <code>--disallow-tools</code> 及用例字段 <code>disallowed_tools</code> 排除指定内置工具）。⚠️ v2.1.283 起机器上装有 git 时，它要求 git 2.31 或更高版本，版本太旧会直接拒绝并说明版本号。</p><p>🆕 <strong>v2.1.287 起 Claude Mods</strong>：插件可以扩展 Claude Code 更深层的运行行为。Anthropic 同版还提供内置的 <code>cc-plugin-you-should-know</code> 审查插件；在支持它的第一方会话中，可用 <code>/plugin enable cc-plugin-you-should-know@builtin</code> 开启。v2.1.292 至 v2.1.318 持续扩充了 Mods 接口（如 <code>prompt.autocomplete</code> 与 <code>prompt.change</code> 事件、<code>$.model.complete</code> 的 prompt 缓存、<code>$.model.fork</code> 的 <code>effort</code> 选项、<code>$.ui.notify</code> 与 <code>$.ui.view({ agentId })</code>、托管 Mod 的 <code>$.prompt.media</code> / <code>$.session.identity()</code> / <code>settings.read</code> 层级改写，以及 <code>tool.check</code> 的 <code>decider: &quot;person&quot;</code> 强制人工审批等）。Mods 属于插件作者侧的扩展能力，普通插件的技能、agent、hook 与 MCP 配置方式不变。</p><blockquote><p>🆕 <strong>skills-dir 插件</strong>：<code>claude plugin init my-tool</code> 会在 <code>~/.claude/skills/my-tool/</code> 脚手架一个带清单的插件，下次启动直接以 <code>my-tool@skills-dir</code> 加载，<strong>无需 Marketplace 也无需 install</strong>。适合个人自用又想要插件目录结构的场景。</p></blockquote><p>发布时，再写一份 <code>.claude-plugin/marketplace.json</code> 目录、推到 GitHub，别人就能 <code>/plugin marketplace add 你的仓库</code> + <code>/plugin install</code>。marketplace.json 顶层是 <code>name</code> / <code>owner</code> / <code>plugins[]</code>，每个插件项至少给 <code>name</code> 与 <code>source</code>（相对路径、<code>github</code>、<code>url</code>、<code>git-subdir</code>、<code>npm</code>，或 v2.1.224 起的 <code>archive</code>——通过 HTTPS 下载 zip，无需 git 或 npm，可选 SHA-256 钉版）。完整 schema 见官方文档。</p><p>⚠️ v2.1.275 起 <code>npm</code> 来源的插件改用 <code>npm pack --ignore-scripts</code> 拉取并做完整性校验，包里的安装脚本不再运行；v2.1.274 起插件与 marketplace 克隆时 Git LFS 文件只留指针、不再下载，需要的话在检出目录里跑 <code>git lfs pull</code>。</p><p>Marketplace 本身除了 git 仓库、本地路径与 URL，v2.1.229 起还支持 <code>command</code> 来源：由一条本地命令（比如 IDE）打印插件目录，每个会话重新解析、免重启生效；v2.1.232 起裸 <code>gitlab.com</code> 仓库 URL（含嵌套子组）也能像 <code>github.com</code> 那样直接克隆。</p><h2 id="团队分发与-settings" tabindex="-1">团队分发与 settings <a class="header-anchor" href="#团队分发与-settings" aria-label="Permalink to &quot;团队分发与 settings&quot;">​</a></h2><p>要让协作者 clone 仓库、信任目录后被<strong>自动提示安装</strong>，在项目 <code>.claude/settings.json</code> 里声明 Marketplace 与默认启用的插件：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;extraKnownMarketplaces&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;company-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;repo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-org/claude-plugins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;enabledPlugins&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;code-formatter@company-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;deployment-tools@company-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>安装作用域三选一：<strong>user</strong>（自己所有项目）、<strong>project</strong>（写进仓库 <code>.claude/settings.json</code>，全体协作者）、<strong>local</strong>（仅自己、仅本仓库）。企业管理员可用托管设置的 <code>strictKnownMarketplaces</code> 锁定/allowlist 允许添加的来源（<code>[]</code> 完全锁死），用户无法覆盖。Marketplace 与缓存状态存在 <code>~/.claude/plugins/</code>（<code>known_marketplaces.json</code>、<code>cache/</code>）。</p><h2 id="版本与更新" tabindex="-1">版本与更新 <a class="header-anchor" href="#版本与更新" aria-label="Permalink to &quot;版本与更新&quot;">​</a></h2><p>Claude Code 按这个顺序解析插件版本：① <code>plugin.json</code> 的 <code>version</code> → ② Marketplace 条目里的 <code>version</code> → ③ 插件源的 git commit SHA。所以<strong>要么每次发布 bump <code>version</code>，要么干脆省略 version、靠 commit SHA 自动区分</strong>——两者都设且忘了改，老版本用户会一直停在缓存里。v2.1.274 起，插件或 marketplace 目录自身没有 git 仓库时，不再从外层的 git 仓库（比如用 git 管理的 <code>~/.claude</code>）取版本号。</p><p>官方 Marketplace 默认开启后台自动更新（启动后随机延迟至多 10 分钟拉取，不打断当前会话，更新后提示你 <code>/reload-plugins</code>）；第三方与本地开发 Marketplace 默认关闭。手动刷新用 <code>/plugin marketplace update</code>。v2.1.280 修复了后台自动更新不走 git 凭证 helper，导致私有仓库的 Marketplace 每次重新克隆或永远不更新。</p><p>记录已装插件的 <code>installed_plugins.json</code> 出问题时，v2.1.283 起的处理更稳妥：遇到本版本读不懂的记录不再改写文件（<code>claude plugin</code> 命令会点出那条记录并说明恢复办法）；整个文件读不了时，先把内容另存到旁边的文件再重建，<code>claude plugin list</code> 会指出这个文件。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ol><li><strong>组件放错层级</strong> —— <code>commands/</code>、<code>skills/</code>、<code>agents/</code>、<code>hooks/</code> 必须在插件根，不能塞进 <code>.claude-plugin/</code>（只放 <code>plugin.json</code>）。</li><li><strong>改了插件却没生效</strong> —— 跑 <code>/reload-plugins</code>；涉及 MCP 工具集变化时加 <code>--force</code>。<code>/reload-skills</code> 不会重载插件。注意 v2.1.221 起用 <code>/plugin</code> 安装的插件在安全的前提下会立即生效，<strong>v2.1.268 起安装、启用、禁用都在关闭 <code>/plugin</code> 菜单时生效</strong>——所以这条排查主要针对「手改了插件文件」的场景。</li><li><strong>推了新 commit 用户却没更新</strong> —— <code>plugin.json</code> 里写死了 <code>version</code> 又没 bump；要么 bump，要么删掉 version 用 SHA。</li><li><strong>URL 直链 Marketplace 里用了相对路径 source</strong> —— 只下载 <code>marketplace.json</code> 本身，相对路径插件文件取不到；改用 <code>github</code>/<code>npm</code>/git URL source，或把 Marketplace 托管成完整 git 仓库。</li><li><strong>引用了插件目录外的文件</strong>（如 <code>../shared-utils</code>） —— 插件安装时会被复制进缓存，外部文件不会跟着走；用 <code>\${CLAUDE_PLUGIN_ROOT}</code> 引用包内文件，跨插件共享用 symlink。</li></ol><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="/Front2Full/manual/agent/claude-code/custom-commands">Commands</a>、<a href="/Front2Full/manual/agent/claude-code/skills">Skills</a>、<a href="/Front2Full/manual/agent/claude-code/agents">Agents</a>——插件打包的三类主要组件</li><li><a href="/Front2Full/manual/agent/claude-code/commands-customization">自定义与扩展 · 插件</a>——<code>/plugin</code>、<code>/reload-plugins</code> 命令速查</li><li><a href="/Front2Full/manual/agent/claude-code/configuration-files">配置文件</a>——<code>settings.json</code> 里的 <code>extraKnownMarketplaces</code>、<code>enabledPlugins</code></li></ul>`,56)])])}const g=s(d,[["render",i]]);export{h as __pageData,g as default};
